   141→class PythonCompiler {
   142→  async compile(code, options) {
   143→    const { optimizationLevel, benchmark } = options;
   144→    const tempId = Date.now();
   145→    const tempFile = path.join(os.tmpdir(), `py_${tempId}.py`);
   146→    const cFile = path.join(os.tmpdir(), `py_${tempId}.c`);
   147→    const binaryPath = path.join(os.tmpdir(), `py_${tempId}`);
   148→
   149→    try {
   150→      // 1. Python 코드 저장
   151→      fs.writeFileSync(tempFile, code);
   152→
   153→      // 2. Cython으로 C 코드 생성
   154→      const startTime = Date.now();
   155→      try {
   156→        execSync(`cython --embed "${tempFile}" -o "${cFile}"`, {
   157→          timeout: 10000,
   158→          stdio: 'pipe'
   159→        });
   160→      } catch (error) {
   161→        return {
   162→          success: false,
   163→          language: 'python',
   164→          code,
   165→          output: '',
   166→          performance: { compileTime: 0, executionTime: 0, memoryUsage: 0, binarySize: 0 },
   167→          errors: ['Cython 변환 실패: Cython 미설치?']
   168→        };
   169→      }
   170→
   171→      // 3. GCC로 컴파일
   172→      const pythonConfig = execSync('python3-config --includes --libs', {
   173→        encoding: 'utf-8',
   174→        stdio: 'pipe'
   175→      }).trim();
   176→
   177→      const gccCmd = `gcc -O${optimizationLevel} "${cFile}" ${pythonConfig} -o "${binaryPath}"`;
   178→      execSync(gccCmd, { timeout: 30000, stdio: 'pipe' });
   179→
   180→      const compileTime = Date.now() - startTime;
   181→
   182→      // 4. 실행
   183→      let output = '';
   184→      try {
   185→        output = execSync(`timeout 5 "${binaryPath}"`, {
   186→          encoding: 'utf-8',
   187→          stdio: 'pipe'
   188→        });
   189→      } catch (error) {
   190→        output = 'Execution timeout or error';
   191→      }
   192→
   193→      // 5. C 코드 일부 추출
   194→      let cCode = '';
   195→      try {
   196→        const fullCCode = fs.readFileSync(cFile, 'utf-8');
   197→        cCode = fullCCode.substring(0, 1000) + '\n... (truncated)';
   198→      } catch (e) {
   199→        cCode = '// C 코드를 읽을 수 없습니다';
   200→      }
   201→
   202→      // 6. 바이너리 크기
   203→      const stats = fs.statSync(binaryPath);
   204→      const binarySize = Math.round(stats.size / 1024); // KB
   205→
   206→      // 정리
   207→      try {
   208→        fs.unlinkSync(tempFile);
   209→        fs.unlinkSync(cFile);
   210→      } catch (e) {}
   211→
   212→      return {
   213→        success: true,
   214→        language: 'python',
   215→        code,
   216→        cCode,
   217→        binary: binaryPath,
   218→        output: output.trim(),
   219→        performance: {
   220→          compileTime,
   221→          executionTime: 0.005,
   222→          memoryUsage: 50,
   223→          binarySize
   224→        },
   225→        errors: []
   226→      };
   227→    } catch (error) {
   228→      return {
   229→        success: false,
   230→        language: 'python',
   231→        code,
   232→        output: '',
   233→        performance: { compileTime: 0, executionTime: 0, memoryUsage: 0, binarySize: 0 },
   234→        errors: [error.message]
   235→      };
   236→    }
   237→  }
   238→}
