import React, { useState, useEffect } from 'react';

/**
 * 간단한 코드 에디터 (Monaco Editor 대신 textarea 사용)
 * 실제 구현에서는 @monaco-editor/react 사용 권장
 */
export default function CodeEditor({
  code,
  language,
  onChange,
  onCompile,
  isCompiling
}) {
  const [lineCount, setLineCount] = useState(1);

  useEffect(() => {
    const count = code.split('\n').length;
    setLineCount(count);
  }, [code]);

  const syntaxHighlight = (text, lang) => {
    // 간단한 문법 강조 (실제 구현에서는 Prism.js 등 사용)
    return text;
  };

  return (
    <div className="code-editor flex flex-col h-full">
      <div className="flex justify-between items-center mb-4 p-4 bg-gray-100 rounded">
        <div>
          <h3 className="text-lg font-bold text-gray-800">
            {language.toUpperCase()} Code
          </h3>
          <p className="text-sm text-gray-600">{lineCount} lines</p>
        </div>
        <button
          onClick={onCompile}
          disabled={isCompiling}
          className={`
            px-6 py-2 rounded-lg font-bold text-white transition-all
            ${isCompiling
              ? 'bg-gray-400 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-700 active:scale-95'
            }
          `}
        >
          {isCompiling ? '⏳ Compiling...' : '▶️ Compile & Run'}
        </button>
      </div>

      <textarea
        value={code}
        onChange={(e) => onChange(e.target.value)}
        className="
          flex-1 p-4 font-mono text-sm bg-gray-900 text-gray-100
          border-l-4 border-blue-600 focus:outline-none focus:ring-2
          focus:ring-blue-400 rounded overflow-auto
        "
        placeholder="Enter your code here..."
        spellCheck="false"
      />
    </div>
  );
}

import React from 'react';

/**
 * 결과 표시 패널 (C 코드, 실행 결과, 성능)
 */
export default function OutputPanel({ result, loading }) {
  if (loading) {
    return (
      <div className="output-panel p-4 bg-gray-100 rounded flex items-center justify-center h-64">
        <div className="text-center">
          <div className="animate-spin text-4xl mb-4">⏳</div>
          <p className="text-gray-600 font-medium">Compiling...</p>
        </div>
      </div>
    );
  }

  if (!result) {
    return (
      <div className="output-panel p-4 bg-gray-100 rounded flex items-center justify-center h-64">
        <p className="text-gray-500">Click "Compile & Run" to see results</p>
      </div>
    );
  }

  if (!result.success) {
    return (
      <div className="output-panel p-4 bg-red-50 rounded border-l-4 border-red-600">
        <h3 className="font-bold text-red-700 mb-2">❌ Compilation Error</h3>
        <div className="bg-red-100 p-3 rounded text-red-800 font-mono text-sm overflow-auto max-h-48">
          {result.errors && result.errors.length > 0
            ? result.errors.map((err, i) => <div key={i}>{err}</div>)
            : 'Unknown error'}
        </div>
      </div>
    );
  }

  return (
    <div className="output-panel space-y-4">
      {/* 생성된 C 코드 */}
      {result.cCode && (
        <div className="bg-gray-100 rounded p-4">
          <div className="flex justify-between items-center mb-2">
            <h3 className="font-bold text-gray-800">📝 Generated C Code</h3>
            <button
              onClick={() => {
                navigator.clipboard.writeText(result.cCode);
                alert('복사되었습니다!');
              }}
              className="text-sm px-2 py-1 bg-blue-600 text-white rounded hover:bg-blue-700"
            >
              Copy
            </button>
          </div>
          <pre className="bg-gray-900 text-gray-100 p-3 rounded overflow-auto max-h-48 font-mono text-xs">
            {result.cCode.substring(0, 500)}
            {result.cCode.length > 500 ? '\n... (truncated)' : ''}
          </pre>
        </div>
      )}

      {/* 실행 결과 */}
      <div className="bg-blue-50 rounded p-4 border-l-4 border-blue-600">
        <h3 className="font-bold text-blue-800 mb-2">✅ Output</h3>
        <pre className="bg-blue-100 text-blue-900 p-3 rounded font-mono text-sm overflow-auto max-h-24">
          {result.output || '(no output)'}
        </pre>
      </div>

      {/* 성능 메트릭 */}
      {result.performance && (
        <div className="grid grid-cols-2 gap-3">
          <div className="bg-green-50 rounded p-3 border-l-4 border-green-600">
            <p className="text-xs text-green-700 font-medium">Compile Time</p>
            <p className="text-lg font-bold text-green-900">
              {result.performance.compileTime}ms
            </p>
          </div>
          <div className="bg-yellow-50 rounded p-3 border-l-4 border-yellow-600">
            <p className="text-xs text-yellow-700 font-medium">Execution Time</p>
            <p className="text-lg font-bold text-yellow-900">
              {result.performance.executionTime}ms
            </p>
          </div>
          <div className="bg-purple-50 rounded p-3 border-l-4 border-purple-600">
            <p className="text-xs text-purple-700 font-medium">Memory Usage</p>
            <p className="text-lg font-bold text-purple-900">
              {result.performance.memoryUsage}MB
            </p>
          </div>
          <div className="bg-orange-50 rounded p-3 border-l-4 border-orange-600">
            <p className="text-xs text-orange-700 font-medium">Binary Size</p>
            <p className="text-lg font-bold text-orange-900">
              {result.performance.binarySize}KB
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

