import React, { useRef } from 'react';
import MonacoEditor from '@monaco-editor/react';

// 언어 ID → Monaco 언어 ID 매핑
const MONACO_LANG = {
  python:     'python',
  c:          'c',
  go:         'go',
  rust:       'rust',
  typescript: 'javascript',
  freelang:   'plaintext',
  fv:         'plaintext',
  java:       'java',
  kotlin:     'kotlin',
  wasm:       'plaintext',
};

export default function CodeEditor({ code, language, onChange, onCompile, isCompiling }) {
  const editorRef = useRef(null);

  const handleEditorMount = (editor) => {
    editorRef.current = editor;
    // Ctrl+Enter / Cmd+Enter 로 컴파일
    editor.addCommand(
      // Monaco keyCodes: CtrlCmd=2048, Enter=3
      2048 | 3,
      () => { if (!isCompiling) onCompile(); }
    );
  };

  const lineCount = code.split('\n').length;

  return (
    <div className="code-editor flex flex-col h-full">
      {/* 헤더 */}
      <div className="flex justify-between items-center p-4 bg-gray-100">
        <div>
          <h3 className="text-lg font-bold text-gray-800">
            {language.toUpperCase()} Code
          </h3>
          <p className="text-xs text-gray-500">{lineCount} lines · Ctrl+Enter로 실행</p>
        </div>
        <button
          onClick={onCompile}
          disabled={isCompiling}
          className={`
            px-6 py-2 rounded-lg font-bold text-white transition-all
            ${isCompiling
              ? 'bg-gray-400 cursor-not-allowed'
              : 'bg-blue-600 hover:bg-blue-700 active:scale-95'
            }
          `}
        >
          {isCompiling ? '⏳ Compiling...' : '▶ Compile & Run'}
        </button>
      </div>

      {/* Monaco Editor */}
      <div className="flex-1 min-h-[320px]">
        <MonacoEditor
          height="100%"
          language={MONACO_LANG[language] || 'plaintext'}
          value={code}
          onChange={(val) => onChange(val ?? '')}
          onMount={handleEditorMount}
          theme="vs-dark"
          options={{
            fontSize: 14,
            minimap: { enabled: false },
            scrollBeyondLastLine: false,
            wordWrap: 'on',
            tabSize: 2,
            automaticLayout: true,
            lineNumbers: 'on',
            renderLineHighlight: 'all',
            cursorBlinking: 'smooth',
          }}
        />
      </div>
    </div>
  );
}

