import React from 'react';

const LANGUAGES = [
  { id: 'python',     name: 'Python',      icon: '🐍', description: 'Cython → C 변환',       status: 'supported' },
  { id: 'c',         name: 'C',           icon: '⚙️', description: '네이티브 최고 성능',     status: 'supported' },
  { id: 'go',        name: 'Go',          icon: '🐹', description: '빠른 컴파일, 모던',      status: 'supported' },
  { id: 'rust',      name: 'Rust',        icon: '🦀', description: '안전성 + 성능',          status: 'experimental' },
  { id: 'typescript',name: 'TypeScript',  icon: '📘', description: 'Node.js 실행',           status: 'supported' },
  { id: 'freelang',  name: 'FreeLang',    icon: '🎨', description: 'FreeLang → C 변환',      status: 'experimental' },
  { id: 'fv',        name: 'FV-Julia',    icon: '🔬', description: 'FV2 → C 변환',           status: 'experimental' },
  { id: 'java',      name: 'Java',        icon: '☕', description: 'JVM (미지원)',            status: 'unsupported' },
  { id: 'kotlin',    name: 'Kotlin',      icon: '🎯', description: 'JVM (미지원)',            status: 'unsupported' },
  { id: 'wasm',      name: 'WebAssembly', icon: '🕸️', description: '구현 예정',              status: 'unsupported' },
];

const STATUS_BADGE = {
  supported:    null,
  experimental: { label: 'BETA', cls: 'bg-yellow-400 text-yellow-900' },
  unsupported:  { label: 'N/A',  cls: 'bg-gray-400 text-white' },
};

export default function LanguageSelector({ selectedLanguage, onSelect }) {
  const handleClick = (lang) => {
    if (lang.status === 'unsupported') return;
    onSelect(lang.id);
  };

  return (
    <div className="language-selector flex flex-wrap gap-2">
      {LANGUAGES.map(lang => {
        const isSelected    = selectedLanguage === lang.id;
        const isUnsupported = lang.status === 'unsupported';
        const badge         = STATUS_BADGE[lang.status];

        return (
          <button
            key={lang.id}
            onClick={() => handleClick(lang)}
            disabled={isUnsupported}
            title={lang.description}
            className={`
              relative px-4 py-2 rounded-lg font-medium transition-all text-sm
              ${isUnsupported
                ? 'bg-gray-100 text-gray-400 cursor-not-allowed opacity-60'
                : isSelected
                  ? 'bg-blue-600 text-white shadow-lg'
                  : 'bg-gray-200 text-gray-800 hover:bg-gray-300'
              }
            `}
          >
            {lang.icon} {lang.name}
            {badge && (
              <span className={`ml-1.5 text-[10px] font-bold px-1 py-0.5 rounded ${badge.cls}`}>
                {badge.label}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

