async compare(request) {
  const { languages, code, testCases = [1, 3, 5] } = request;
  const results = [];

  for (const language of languages) {
    try {
      // 1회 컴파일
      const compiled = await this.compile({ language, code, optimizationLevel: 2, benchmark: true });
      if (!compiled.success) continue;

      // testCases 횟수만큼 반복 실행해 평균 측정
      const executionTimes = [];
      for (const n of testCases) {
        const runs = [];
        for (let i = 0; i < n; i++) {
          const r = await this.compile({ language, code, optimizationLevel: 2, benchmark: false });
          if (r.success) runs.push(r.performance.executionTime);
        }
        const avg = runs.length > 0
          ? runs.reduce((a, b) => a + b, 0) / runs.length
          : compiled.performance.executionTime;
        executionTimes.push(+avg.toFixed(3));
      }

      results.push({
        language,
        executionTime: executionTimes,
        binarySize:    compiled.performance.binarySize,
        memoryUsage:   compiled.performance.memoryUsage,
        compileTime:   compiled.performance.compileTime
      });
    } catch (err) {
      console.error(`compare error [${language}]:`, err.message);
    }
  }

  return { success: results.length > 0, results };
}

