const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');

// 허용된 최적화 레벨 화이트리스트
const ALLOWED_OPT_LEVELS = new Set([0, 1, 2, 3]);

// 코드 크기 제한 (10KB)
const MAX_CODE_SIZE = 10 * 1024;

/**
 * 안전한 임시 파일 ID 생성 (예측 불가)
 */
function safeTempId() {
  return crypto.randomBytes(8).toString('hex');
}

/**
 * 임시 파일 안전 삭제
 */
function safeUnlink(...files) {
  for (const f of files) {
    try { if (f && fs.existsSync(f)) fs.unlinkSync(f); } catch (_) {}
  }
}

/**
 * 실제 실행 시간 측정 (ms, 소수점 3자리)
 */
function measureExecTime(binaryPath, args = []) {
  const start = process.hrtime.bigint();
  execFileSync(binaryPath, args, { timeout: 5000, stdio: 'pipe' });
  const end = process.hrtime.bigint();
  return Number(end - start) / 1_000_000; // ns → ms
}

/**
 * 컴파일러 서비스
 */
class CompilerService {
  constructor() {
    this.compilers = {
      c:          new CCompiler(),
      python:     new PythonCompiler(),
      go:         new GoCompiler(),
      rust:       new RustCompiler(),
      typescript: new TypeScriptCompiler(),
      freelang:   new FreeLangCompiler(),
      fv:         new FVCompiler(),
    };
  }

  async compile(request) {
    const { language, code, optimizationLevel = 2, benchmark = false } = request;

    // 언어 검증
    if (!this.compilers[language]) {
      return {
        success: false,
        language,
        errors: [`지원하지 않는 언어: ${language}`]
      };
    }

    // 코드 크기 검증
    if (Buffer.byteLength(code, 'utf8') > MAX_CODE_SIZE) {
      return {
        success: false,
        language,
        errors: [`코드 크기 초과 (최대 ${MAX_CODE_SIZE / 1024}KB)`]
      };
    }

    // 최적화 레벨 검증
    const optLevel = parseInt(optimizationLevel, 10);
    if (!ALLOWED_OPT_LEVELS.has(optLevel)) {
      return {
        success: false,
        language,
        errors: ['optimizationLevel은 0~3만 허용됩니다']
      };
    }

    try {
      return await this.compilers[language].compile(code, { optimizationLevel: optLevel, benchmark });
    } catch (error) {
      return {
        success: false,
        language,
        output: '',
        performance: { compileTime: 0, executionTime: 0, memoryUsage: 0, binarySize: 0 },
        errors: [error.message]
      };
    }
  }

  async compare(request) {
    const { languages, code, testCases = [10, 20, 30, 40] } = request;
    const results = [];

    for (const language of languages) {
      try {
        const result = await this.compile({ language, code, optimizationLevel: 2, benchmark: true });
        if (result.success) {
          results.push({
            language,
            executionTime: testCases.map(n => result.performance.executionTime * (n / 10)),
            binarySize:    result.performance.binarySize,
            memoryUsage:   result.performance.memoryUsage,
            compileTime:   result.performance.compileTime
          });
        }
      } catch (err) {
        console.error(`compare error [${language}]:`, err.message);
      }
    }

    return { success: results.length > 0, results };
  }
}

// ─── Python (Cython) ──────────────────────────────────────────────────────────
class PythonCompiler {
  async compile(code, options) {
    const { optimizationLevel } = options;
    const id = safeTempId();
    const tempFile   = path.join(os.tmpdir(), `py_${id}.py`);
    const cFile      = path.join(os.tmpdir(), `py_${id}.c`);
    const binaryPath = path.join(os.tmpdir(), `py_${id}`);

    try {
      fs.writeFileSync(tempFile, code, { mode: 0o600 });

      const startTime = Date.now();

      // Cython → C
      try {
        execFileSync('cython', ['--embed', tempFile, '-o', cFile], {
          timeout: 10000, stdio: 'pipe'
        });
      } catch (e) {
        return err('python', code, 'Cython 변환 실패 (cython 미설치 또는 문법 오류):\n' + e.stderr?.toString());
      }

      // python3-config
      let pythonFlags;
      try {
        pythonFlags = execFileSync('python3-config', ['--includes', '--libs'], {
          encoding: 'utf-8', stdio: 'pipe'
        }).trim();
      } catch (e) {
        return err('python', code, 'python3-config 실패');
      }

      // GCC
      const flagTokens = pythonFlags.split(/\s+/).filter(Boolean);
      try {
        execFileSync('gcc', [
          `-O${optimizationLevel}`, cFile,
          ...flagTokens,
          '-o', binaryPath
        ], { timeout: 30000, stdio: 'pipe' });
      } catch (e) {
        return err('python', code, 'GCC 컴파일 실패:\n' + e.stderr?.toString());
      }

      const compileTime = Date.now() - startTime;

      // 실행 + 실제 시간 측정
      let output = '';
      let executionTime = 0;
      try {
        const t0 = process.hrtime.bigint();
        output = execFileSync(binaryPath, [], {
          encoding: 'utf-8', timeout: 5000, stdio: 'pipe'
        });
        executionTime = Number(process.hrtime.bigint() - t0) / 1_000_000;
      } catch (e) {
        output = e.stdout?.toString() || 'Execution timeout or error';
      }

      const binarySize = Math.round(fs.statSync(binaryPath).size / 1024);

      let cCode = '// C 코드를 읽을 수 없음';
      try {
        const full = fs.readFileSync(cFile, 'utf-8');
        cCode = full.slice(0, 1000) + (full.length > 1000 ? '\n... (truncated)' : '');
      } catch (_) {}

      return {
        success: true, language: 'python', code, cCode,
        output: output.trim(),
        performance: { compileTime, executionTime: +executionTime.toFixed(3), memoryUsage: 0, binarySize },
        errors: []
      };
    } finally {
      safeUnlink(tempFile, cFile);
    }
  }
}

