        return err('fv', code, 'FV 컴파일 실패:\n' + (e.stderr?.toString() || e.message));
      }

      fs.writeFileSync(cFile, cCode, { mode: 0o600 });

      try {
        execFileSync('gcc', [`-O${optimizationLevel}`, cFile, '-o', binaryPath, '-lm'], {
          timeout: 30000, stdio: 'pipe'
        });
      } catch (e) {
