      return {
        success: true, language: 'fv', code,
        cCode: cCode.slice(0, 1000) + (cCode.length > 1000 ? '\n... (truncated)' : ''),
        output: output.trim(),
        performance: { compileTime, executionTime: +executionTime.toFixed(3), memoryUsage: 0, binarySize },
        errors: []
      };
    } finally {
      safeUnlink(fvFile, cFile);
    }
  }
}

// ─── 헬퍼 ────────────────────────────────────────────────────────────────────
function err(language, code, message) {
  return {
    success: false, language, code, output: '',
    performance: { compileTime: 0, executionTime: 0, memoryUsage: 0, binarySize: 0 },
    errors: [message]
  };
}

