import React, { useState } from 'react';
import MonacoEditor from '@monaco-editor/react';
import ComparisonChart from '../components/ComparisonChart';
import { useCompiler } from '../hooks/useCompiler';

const LANGUAGES = [
  { id: 'c',          name: 'C',          icon: '⚙️', mono: 'c' },
  { id: 'go',         name: 'Go',         icon: '🐹', mono: 'go' },
  { id: 'python',     name: 'Python',     icon: '🐍', mono: 'python' },
  { id: 'typescript', name: 'TypeScript', icon: '📘', mono: 'javascript' },
  { id: 'rust',       name: 'Rust',       icon: '🦀', mono: 'rust' },
  { id: 'fv',         name: 'FV-Julia',   icon: '🔬', mono: 'plaintext' },
];

// 언어별 기본 예제 (Fibonacci)
const DEFAULT_CODE = {
  c: `#include <stdio.h>

int fib(int n) {
    if (n <= 1) return n;
    return fib(n-1) + fib(n-2);
}

int main() {
    printf("%d\\n", fib(10));
    return 0;
}`,
  go: `package main
import "fmt"

func fib(n int) int {
    if n <= 1 { return n }
    return fib(n-1) + fib(n-2)
}

func main() {
    fmt.Println(fib(10))
}`,
  python: `def fib(n):
    return n if n <= 1 else fib(n-1) + fib(n-2)

print(fib(10))`,
  typescript: `function fib(n: number): number {
    return n <= 1 ? n : fib(n-1) + fib(n-2);
}
console.log(fib(10));`,
  rust: `fn fib(n: u32) -> u32 {
    if n <= 1 { return n; }
    fib(n-1) + fib(n-2)
}

fn main() {
    println!("{}", fib(10));
}`,
  fv: `fn fib(n: int) -> int {
    if n <= 1 { return n }
    return fib(n - 1) + fib(n - 2)
}

fn main() {
    println(fib(10))
}`,
};

export default function Comparison() {
  const [selectedLanguages, setSelectedLanguages] = useState(['c', 'go', 'python']);
  const [primaryLang, setPrimaryLang] = useState('c');
  const [codes, setCodes] = useState(DEFAULT_CODE);
  const [comparisonResult, setComparisonResult] = useState(null);

  const { loading, compare } = useCompiler();

  const handleLanguageToggle = (id) => {
    if (selectedLanguages.includes(id)) {
      if (selectedLanguages.length === 1) return; // 최소 1개
      setSelectedLanguages(selectedLanguages.filter(l => l !== id));
      if (primaryLang === id) setPrimaryLang(selectedLanguages.find(l => l !== id));
    } else {
      if (selectedLanguages.length >= 5) return alert('최대 5개');
      setSelectedLanguages([...selectedLanguages, id]);
    }
  };

  const handleCompare = async () => {
    // 각 언어별로 해당 언어 코드를 사용해 비교
    const results = [];
    for (const lang of selectedLanguages) {
      const r = await compare([lang], codes[lang] || codes[primaryLang]);
      if (r?.results?.[0]) results.push(r.results[0]);
    }
    setComparisonResult({ success: results.length > 0, results });
  };

  const monoLang = LANGUAGES.find(l => l.id === primaryLang)?.mono || 'plaintext';

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">

        {/* 헤더 */}
        <div className="mb-6">
          <h1 className="text-4xl font-bold text-gray-900 mb-2">
            ⚡ Language Performance Comparison
          </h1>
          <p className="text-gray-600">같은 알고리즘을 여러 언어로 실행해 성능을 비교합니다</p>
        </div>

        {/* 언어 선택 */}
        <div className="bg-white rounded-lg shadow p-6 mb-6">
          <h2 className="font-bold text-lg text-gray-800 mb-4">
            언어 선택 ({selectedLanguages.length}/5)
          </h2>
          <div className="flex flex-wrap gap-3">
            {LANGUAGES.map(lang => {
              const selected = selectedLanguages.includes(lang.id);
              const isPrimary = primaryLang === lang.id;
              return (
                <div key={lang.id} className="flex flex-col items-center gap-1">
                  <button
                    onClick={() => handleLanguageToggle(lang.id)}
                    className={`
                      px-4 py-2 rounded-lg font-medium border-2 transition-all
                      ${selected
                        ? 'bg-blue-600 text-white border-blue-600'
                        : 'bg-white text-gray-600 border-gray-300 hover:border-blue-400'}
                    `}
                  >
                    {lang.icon} {lang.name}
                  </button>
                  {selected && (
                    <button
                      onClick={() => setPrimaryLang(lang.id)}
                      className={`text-xs px-2 py-0.5 rounded ${isPrimary ? 'bg-green-500 text-white' : 'bg-gray-200 text-gray-600 hover:bg-gray-300'}`}
                    >
                      {isPrimary ? '✎ 편집 중' : '편집'}
                    </button>
                  )}
                </div>
              );
            })}
          </div>
          <p className="text-xs text-gray-400 mt-3">각 언어는 독립적인 코드로 실행됩니다 · "편집" 버튼으로 언어별 코드 수정 가능</p>
        </div>

        {/* 코드 편집 (언어별 탭) */}
        <div className="bg-white rounded-lg shadow mb-6 overflow-hidden">
          <div className="flex border-b">
            {selectedLanguages.map(id => {
              const lang = LANGUAGES.find(l => l.id === id);
              return (
                <button
                  key={id}
                  onClick={() => setPrimaryLang(id)}
                  className={`px-4 py-2 text-sm font-medium border-r transition-colors
                    ${primaryLang === id ? 'bg-gray-900 text-white' : 'bg-gray-100 text-gray-600 hover:bg-gray-200'}`}
                >
                  {lang?.icon} {lang?.name}
                </button>
              );
            })}
          </div>
          <div className="h-64">
            <MonacoEditor
              height="100%"
              language={monoLang}
              value={codes[primaryLang] || ''}
              onChange={(val) => setCodes(prev => ({ ...prev, [primaryLang]: val ?? '' }))}
              theme="vs-dark"
              options={{ fontSize: 13, minimap: { enabled: false }, scrollBeyondLastLine: false, automaticLayout: true }}
            />
          </div>
        </div>

        {/* 비교 버튼 */}
        <div className="mb-6">
          <button
            onClick={handleCompare}
            disabled={loading || selectedLanguages.length < 2}
            className={`
              px-8 py-3 rounded-lg font-bold text-white transition-all
              ${loading || selectedLanguages.length < 2
                ? 'bg-gray-400 cursor-not-allowed'
                : 'bg-blue-600 hover:bg-blue-700 active:scale-95'}
            `}
          >
            {loading ? '⏳ 비교 중...' : '📊 성능 비교 실행'}
          </button>
          <span className="ml-3 text-sm text-gray-500">각 언어를 실제 컴파일 후 측정합니다</span>
        </div>

        {/* 결과 */}
        {comparisonResult && (
          <div className="space-y-6">
            <div className="bg-white rounded-lg shadow p-6">
              <ComparisonChart results={comparisonResult.results} />
            </div>

            <div className="bg-white rounded-lg shadow p-6">
              <h3 className="font-bold text-lg text-gray-800 mb-4">상세 결과</h3>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead className="bg-gray-100 border-b-2 border-gray-300">
                    <tr>
                      <th className="px-4 py-2 text-left font-bold text-gray-700">언어</th>
                      <th className="px-4 py-2 text-right font-bold text-gray-700">실행시간 (ms)</th>
                      <th className="px-4 py-2 text-right font-bold text-gray-700">바이너리 (KB)</th>
                      <th className="px-4 py-2 text-right font-bold text-gray-700">컴파일 (ms)</th>
                      <th className="px-4 py-2 text-right font-bold text-gray-700">출력</th>
                    </tr>
                  </thead>
                  <tbody>
                    {comparisonResult.results.map((r, i) => (
                      <tr key={i} className={`border-b hover:bg-gray-50 ${i === 0 ? 'bg-green-50' : ''}`}>
                        <td className="px-4 py-2 font-bold text-gray-900">
                          {LANGUAGES.find(l => l.id === r.language)?.icon} {r.language.toUpperCase()}
                          {i === 0 && <span className="ml-2 text-xs bg-green-500 text-white px-1 rounded">fastest</span>}
                        </td>
                        <td className="px-4 py-2 text-right font-mono text-gray-700">
                          {r.executionTime?.[0]?.toFixed(3)}
                        </td>
                        <td className="px-4 py-2 text-right text-gray-700">{r.binarySize || '-'}</td>
                        <td className="px-4 py-2 text-right text-gray-700">{r.compileTime}</td>
                        <td className="px-4 py-2 text-right font-mono text-xs text-gray-500 max-w-xs truncate">
                          {r.output || '-'}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {!comparisonResult && (
          <div className="bg-blue-50 rounded-lg p-6 border-l-4 border-blue-600">
            <h3 className="font-bold text-blue-900 mb-2">💡 사용법</h3>
            <ul className="text-sm text-blue-800 space-y-1">
              <li>✅ 2~5개 언어를 선택 후 "성능 비교 실행" 클릭</li>
              <li>✅ 각 언어 탭에서 코드를 개별 수정 가능</li>
              <li>✅ 실제 컴파일 후 실행시간을 측정합니다</li>
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}

