        </div>

        {/* 코드 편집 (언어별 탭) */}
        <div className="bg-white rounded-lg shadow mb-6 overflow-hidden">
          <div className="flex border-b">
            {selectedLanguages.map(id => {
              const lang = LANGUAGES.find(l => l.id === id);
              return (
                <button
