              language={monoLang}
              value={codes[primaryLang] || ''}
              onChange={(val) => setCodes(prev => ({ ...prev, [primaryLang]: val ?? '' }))}
              theme="vs-dark"
              options={{ fontSize: 13, minimap: { enabled: false }, scrollBeyondLastLine: false, automaticLayout: true }}
            />
