import React from 'react';

const LANG_COLORS = {
  c:          '#ef4444',
  go:         '#3b82f6',
  python:     '#f59e0b',
  typescript: '#8b5cf6',
  rust:       '#f97316',
  fv:         '#10b981',
};

export default function ComparisonChart({ results }) {
  if (!results || results.length === 0) {
    return (
      <div className="p-4 bg-gray-100 rounded text-center text-gray-500">
        비교 데이터 없음
      </div>
    );
  }

  // 실행시간 기준 정렬 (빠른 순)
  const sorted = [...results].sort(
    (a, b) => (a.executionTime?.[0] ?? 0) - (b.executionTime?.[0] ?? 0)
  );

  const maxTime = Math.max(...sorted.map(r => r.executionTime?.[0] ?? 0));
  const fastest = sorted[0]?.executionTime?.[0] ?? 0;

  return (
    <div className="space-y-3">
      <h3 className="font-bold text-lg text-gray-800">📊 실행시간 비교</h3>

      {sorted.map((r, i) => {
        const time = r.executionTime?.[0] ?? 0;
        const pct = maxTime > 0 ? (time / maxTime) * 100 : 0;
        const ratio = fastest > 0 ? (time / fastest).toFixed(1) : '1.0';
        const color = LANG_COLORS[r.language] || '#6b7280';

        return (
          <div key={r.language} className="flex items-center gap-3">
            {/* 순위 */}
            <div className="w-5 text-center text-sm font-bold text-gray-400">{i + 1}</div>

            {/* 언어명 */}
            <div className="w-24 text-sm font-bold text-gray-700 truncate">
              {r.language.toUpperCase()}
            </div>

            {/* 바 */}
            <div className="flex-1 bg-gray-100 rounded-full h-7 overflow-hidden">
              <div
                className="h-full rounded-full flex items-center justify-end pr-2 transition-all duration-500"
                style={{ width: `${Math.max(pct, 4)}%`, backgroundColor: color }}
              >
                <span className="text-white text-xs font-bold whitespace-nowrap">
                  {time.toFixed(3)}ms
                </span>
              </div>
            </div>

            {/* 배율 */}
            <div className="w-14 text-right text-xs text-gray-500">
              {i === 0
                ? <span className="text-green-600 font-bold">fastest</span>
                : <span>{ratio}×</span>
              }
            </div>
          </div>
        );
      })}

      <p className="text-xs text-gray-400 pt-2 border-t">
        실제 컴파일 후 실행시간 측정 · 낮을수록 빠름
      </p>
    </div>
  );
}

