const express = require('express');
const { CompilerService } = require('../services/CompilerService');

const router = express.Router();
const compiler = new CompilerService();

// 언어별 테스트 케이스: {code, expectedOutput}
const TEST_CASES = {
  c: {
    code: '#include<stdio.h>\nint main(){printf("VERIFY_OK");return 0;}',
    expected: 'VERIFY_OK'
  },
  go: {
    code: 'package main\nimport "fmt"\nfunc main(){fmt.Print("VERIFY_OK")}',
    expected: 'VERIFY_OK'
  },
  python: {
    code: 'print("VERIFY_OK", end="")',
    expected: 'VERIFY_OK'
  },
  typescript: {
    code: 'process.stdout.write("VERIFY_OK")',
    expected: 'VERIFY_OK'
  },
  rust: {
    code: 'fn main(){print!("VERIFY_OK");}',
    expected: 'VERIFY_OK'
  },
  fv: {
    code: 'fn main() {\n  print("VERIFY_OK")\n}',
    expected: 'VERIFY_OK'
  },
  freelang: {
    code: 'println("VERIFY_OK")',
    expected: 'VERIFY_OK'
  },
};

/**
 * GET /api/status
 * 모든 언어를 실제 컴파일·실행해서 상태 반환
 * 클로드가 배포 후 자동 검증에 사용
 */
router.get('/', async (req, res) => {
  const startedAt = new Date().toISOString();
  const results = {};
  let passed = 0;
  let failed = 0;

  for (const [lang, tc] of Object.entries(TEST_CASES)) {
    const t0 = Date.now();
    try {
      const r = await compiler.compile({
        language: lang,
        code: tc.code,
        optimizationLevel: 2,
        benchmark: false
      });

      const elapsed = Date.now() - t0;
      const outputMatch = r.output?.trim() === tc.expected;

      if (r.success && outputMatch) {
        passed++;
        results[lang] = {
          status: 'pass',
          output: r.output,
          execTime: r.performance?.executionTime,
          compileTime: r.performance?.compileTime,
          elapsed
        };
      } else {
        failed++;
        results[lang] = {
          status: 'fail',
          reason: !r.success
            ? r.errors?.[0] || 'compile failed'
            : `output mismatch: got "${r.output}" expected "${tc.expected}"`,
          elapsed
        };
      }
    } catch (err) {
      failed++;
      results[lang] = {
        status: 'error',
        reason: err.message,
        elapsed: Date.now() - t0
      };
    }
  }

  const total = passed + failed;
  const score = `${passed}/${total}`;
  const allPassed = failed === 0;

  res.status(allPassed ? 200 : 207).json({
    success: allPassed,
    score,
    passed,
    failed,
    startedAt,
    finishedAt: new Date().toISOString(),
    languages: results
  });
});

module.exports = router;

