import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

const API_BASE = import.meta.env.VITE_API_URL || '';

const STATUS_META = {
  c:          { icon: '⚙️',  name: 'C' },
  go:         { icon: '🐹', name: 'Go' },
  python:     { icon: '🐍', name: 'Python' },
  typescript: { icon: '📘', name: 'TypeScript' },
  rust:       { icon: '🦀', name: 'Rust' },
  fv:         { icon: '🔬', name: 'FV-Julia' },
  freelang:   { icon: '🎨', name: 'FreeLang' },
};

export default function Status() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [lastChecked, setLastChecked] = useState(null);

  const runCheck = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE}/api/status`, { timeout: 120000 });
      // 실행시간 순 정렬 (pass 먼저, 그 다음 fail)
      const langs = res.data.languages || {};
      const sorted = Object.entries(langs).sort(([, a], [, b]) => {
        if (a.status === 'pass' && b.status !== 'pass') return -1;
        if (a.status !== 'pass' && b.status === 'pass') return 1;
        return (a.execTime ?? 9999) - (b.execTime ?? 9999);
      });
      setData({ ...res.data, sortedLangs: sorted });
      setLastChecked(new Date());
    } catch (e) {
      setData({ error: e.message });
    } finally {
      setLoading(false);
    }
  }, []);

  // 페이지 진입 시 자동 실행
  useEffect(() => { runCheck(); }, [runCheck]);

  const score = data?.score;
  const allPass = data?.success;

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-3xl mx-auto">

        {/* 헤더 */}
        <div className="flex items-center justify-between mb-6">
          <div>
            <h1 className="text-3xl font-bold text-gray-900">🔍 자동 검증 현황</h1>
            <p className="text-gray-500 text-sm mt-1">
              각 언어를 실제 컴파일·실행해서 검증합니다
            </p>
          </div>
          <button
            onClick={runCheck}
            disabled={loading}
            className={`px-5 py-2 rounded-lg font-bold text-white transition-all
              ${loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700 active:scale-95'}`}
          >
            {loading ? '⏳ 검증 중...' : '🔄 재검증'}
          </button>
        </div>

        {/* 로딩 */}
        {loading && !data && (
          <div className="bg-white rounded-xl shadow p-10 text-center">
            <div className="text-4xl mb-3 animate-pulse">⚙️</div>
            <p className="text-gray-600 font-medium">각 언어를 컴파일 중입니다...</p>
            <p className="text-gray-400 text-sm mt-1">최대 60초 소요</p>
          </div>
        )}

        {/* 에러 */}
        {data?.error && (
          <div className="bg-red-50 border-l-4 border-red-500 rounded-lg p-4">
            <p className="text-red-700 font-bold">서버 연결 실패</p>
            <p className="text-red-600 text-sm font-mono">{data.error}</p>
          </div>
        )}

        {/* 결과 */}
        {data?.sortedLangs && (
          <>
            {/* 요약 배너 */}
            <div className={`rounded-xl p-5 mb-6 flex items-center justify-between
              ${allPass ? 'bg-green-50 border-2 border-green-400' : 'bg-yellow-50 border-2 border-yellow-400'}`}>
              <div>
                <p className={`text-2xl font-bold ${allPass ? 'text-green-700' : 'text-yellow-700'}`}>
                  {allPass ? '✅ 전체 통과' : `⚠️ ${data.failed}개 실패`}
                </p>
                <p className="text-gray-600 text-sm mt-1">
                  {lastChecked && `마지막 검증: ${lastChecked.toLocaleTimeString('ko-KR')}`}
                </p>
              </div>
              <div className="text-right">
                <p className="text-4xl font-black text-gray-800">{score}</p>
                <p className="text-gray-500 text-sm">언어 통과</p>
              </div>
            </div>

            {/* 언어별 결과 */}
            <div className="space-y-3">
              {data.sortedLangs.map(([lang, r]) => {
                const meta = STATUS_META[lang] || { icon: '?', name: lang };
                const isPass = r.status === 'pass';
                return (
                  <div key={lang}
                    className={`bg-white rounded-xl shadow p-4 flex items-center gap-4
                      border-l-4 ${isPass ? 'border-green-400' : 'border-red-400'}`}>

                    {/* 아이콘 + 이름 */}
                    <div className="w-32">
                      <span className="text-xl">{meta.icon}</span>
                      <span className="ml-2 font-bold text-gray-800">{meta.name}</span>
                    </div>

                    {/* 상태 배지 */}
                    <div className={`px-3 py-1 rounded-full text-xs font-bold
                      ${isPass ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {isPass ? 'PASS' : 'FAIL'}
                    </div>

                    {/* 실행 시간 */}
                    {isPass && (
                      <div className="flex gap-4 text-sm text-gray-600">
                        <span>실행 <b className="text-gray-800">{r.execTime}ms</b></span>
                        <span>컴파일 <b className="text-gray-800">{r.compileTime}ms</b></span>
                      </div>
                    )}

                    {/* 실패 이유 */}
                    {!isPass && (
                      <p className="text-red-600 text-sm font-mono truncate flex-1">{r.reason}</p>
                    )}
                  </div>
                );
              })}
            </div>

            {/* 타임스탬프 */}
            <p className="text-center text-gray-400 text-xs mt-6">
              검증 시작: {data.startedAt} · 완료: {data.finishedAt}
            </p>
          </>
        )}
      </div>
    </div>
  );
}

